    private final CompletableFuture<HolderLookup.Provider> lookupProvider;

    public EpicfightAnimationSequences(PackOutput packOutput, CompletableFuture<HolderLookup.Provider> lookupProvider) {
        super(packOutput);
        this.lookupProvider = lookupProvider;
    }

